INSERT INTO s503c_cards VALUES
(2421,'canon','exodus',32,33,$n$And Yahuah (LORD) said unto Moses, Whosoever has sinned against me, him will I blot out of my book.$n$,'canon','revelation',3,5,$n$thread:effort-over-accomplishment | Blotting principle anchored at Sinai → restated in NT — names blotted from wheat, not tares$n$,$n$Revelation 3:5 — *He that overcometh, the same shall be clothed in white raiment; and I will not blot out his name out of the book of life, but I will confess his name before my Father, and before his angels.* *And Yahuah (LORD) said unto Moses, Whosoever has sinned against me, him will I blot out of my book.* (Exodus 32:33) At Sinai the name can be blotted out of the book. Here the same book comes up again, and the one who overcomes keeps his name in it. The promise only means something because the blotting is real. Yahusha (Jesus) says he will *not blot out his name*, and the warning at the mountain and the promise at the end turn out to be one voice.$n$,229,$n$Blotting principle anchored at Sinai → restated in NT — names blotted from wheat, not tares$n$,$n$Revelation 3:5 — *I will not blot out his name out of the book of life.* The name that can be blotted out at Sinai is the name kept for the one who overcomes.$n$),
(2436,'canon','leviticus',26,40,$n$If they shall confess their iniquity, and the iniquity of their fathers, with their trespass which they trespassed against me, and that also they have walked contrary unto me;$n$,'canon','daniel',9,5,$n$thread:effort-over-accomplishment | The Torah pattern of fathers'-confession lived in Daniel$n$,$n$Daniel 9:5 — *We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from thy precepts and from thy judgments:* *If they shall confess their iniquity, and the iniquity of their fathers, with their trespass which they trespassed against me, and that also they have walked contrary unto me;* (Leviticus 26:40) Moses names what the scattered will do: confess their own iniquity and the iniquity of their fathers. Daniel does exactly that. He does not excuse himself or the fathers. He says *we have sinned*, and he measures it against the precepts and judgments, so Torah is still the line he fell from. The fall is named out loud, and the naming is the rising.$n$,229,$n$The Torah pattern of fathers'-confession lived in Daniel$n$,$n$Daniel 9:5 — *even by departing from thy precepts and from thy judgments.* Daniel confesses the departure from Torah by name, as the law of Moses said the scattered would.$n$),
(2447,'canon','1-kings',8,46,$n$If they sin against you, (for there is no man that sins not,) and you be angry with them, and deliver them to the enemy, so that they carry them away captives unto the land of the enemy, far or near;$n$,'canon','ecclesiastes',7,20,$n$thread:effort-over-accomplishment | No man sinneth not = no just man on earth that sinneth not$n$,$n$Ecclesiastes 7:20 — *For there is not a just man upon earth, that doeth good, and sinneth not.* *If they sin against you, (for there is no man that sins not,) and you be angry with them, and deliver them to the enemy, so that they carry them away captives unto the land of the enemy, far or near;* (1 Kings 8:46) Solomon prays *no man that sinneth not*, and the preacher says the same of the just: there is not one on earth who does good and never sins. Put side by side, they leave no room for a just man who never fell. Nobody is that man, so the line between the just and the wicked has to be drawn somewhere after the fall.$n$,229,$n$No man sinneth not = no just man on earth that sinneth not$n$,$n$Ecclesiastes 7:20 — *For there is not a just man upon earth, that doeth good, and sinneth not.* No just man on earth is without sin, so the fall cannot be what divides the just from the wicked.$n$),
(2432,'canon','job',42,6,$n$Wherefore I abhor myself, and repent in dust and ashes.$n$,'canon','ezekiel',36,31,$n$thread:effort-over-accomplishment | I abhor myself = ye shall loathe yourselves — same posture, two witnesses$n$,$n$Ezekiel 36:31 — *Then shall ye remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* *Wherefore I abhor myself, and repent in dust and ashes.* (Job 42:6) Job sees Yahuah (LORD) and abhors himself in dust and ashes. Ezekiel says the gathered house will do the same once the new heart is in them: they will remember their ways and *lothe yourselves in your own sight*. Two witnesses, one posture. The head goes down first, and mercy is what lifts it.$n$,229,$n$I abhor myself = ye shall loathe yourselves — same posture, two witnesses$n$,$n$Ezekiel 36:31 — *shall lothe yourselves in your own sight for your iniquities and for your abominations.* The new heart's first act is to loathe itself, which is exactly what Job did in the dust.$n$),
(2449,'canon','psalms',14,1,$n$The fool has said in his heart, There is no Elohim (God). They are corrupt, they have done abominable works, there is none that does good.$n$,'canon','romans',3,10,$n$thread:effort-over-accomplishment | The fool said in his heart → none righteous, no, not one$n$,$n$Romans 3:10 — *As it is written, There is none righteous, no, not one:* *The fool has said in his heart, There is no Elohim (God). They are corrupt, they have done abominable works, there is none that does good.* (Psalm 14:1) The psalm's fool says in his heart there is no Elohim (God), and the psalm closes the door on every man: *there is none that doeth good*. Paul writes it down as scripture and says it plainly, none righteous, not one. The verdict on all flesh was old before he wrote it. It is the ground the just man falls on, and what sets him apart is that he rises.$n$,229,$n$The fool said in his heart → none righteous, no, not one$n$,$n$Romans 3:10 — *There is none righteous, no, not one.* Paul quotes the old verdict that no one is righteous, so no man is just by a clean record.$n$),
(2452,'canon','psalms',19,1,$n$The heavens declare the glory of Elohim (God); and the firmament shows his handywork.$n$,'canon','romans',1,20,$n$thread:effort-over-accomplishment | The witness given → the verdict pronounced$n$,$n$Romans 1:20 — *For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:* *The heavens declare the glory of Elohim (God); and the firmament shows his handywork.* (Psalm 19:1) The heavens declare, and Paul says what follows from it: the maker is plainly seen in the things he made, so they are *without excuse*. The witness has been given to every man. The charge is not that men fell. It is what a man does with what he has been shown, and the wicked is the one who turns from it.$n$,229,$n$The witness given → the verdict pronounced$n$,$n$Romans 1:20 — *the invisible things of him from the creation of the world are clearly seen.* The witness in creation is given to all, which is why no one can plead that he was never shown.$n$),
(2442,'canon','psalms',25,11,$n$For your name’s sake, O Yahuah (LORD), pardon my iniquity; for it is great.$n$,'canon','isaiah',48,9,$n$thread:effort-over-accomplishment | For thy name's sake (David) → for my name's sake (Yahuah, Isaiah)$n$,$n$Isaiah 48:9 — *For my name’s sake will I defer mine anger, and for my praise will I refrain for thee, that I cut thee not off.* *For your name’s sake, O Yahuah (LORD), pardon my iniquity; for it is great.* (Psalm 25:11) David asks pardon *for thy name’s sake*, because his iniquity is great. Yahuah (LORD) answers from his own mouth in the same words, *for my name’s sake*, and holds back his anger and does not cut them off. The gift is for the name, not for anything the house earned, and David prays like a man who knows it.$n$,229,$n$For thy name's sake (David) → for my name's sake (Yahuah, Isaiah)$n$,$n$Isaiah 48:9 — *For my name’s sake will I defer mine anger, and for my praise will I refrain for thee.* Yahuah (LORD) holds back his anger for his own name's sake, which is the ground David prays from.$n$),
(2410,'canon','proverbs',24,16,$n$For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.$n$,'canon','psalms',37,24,$n$thread:effort-over-accomplishment | Though he fall, he shall not be utterly cast down — the catching hand$n$,$n$Psalm 37:24 — *Though he fall, he shall not be utterly cast down: for Yahuah (LORD) upholdeth him with his hand.* *For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.* (Proverbs 24:16) The proverb says the just man rises. The psalm shows whose hand lifts him. He falls, and he *shall not be utterly cast down*, because Yahuah (LORD) holds him up. The rising is not the man's own strength alone, and the one who holds him is the same one who gave him the new heart.$n$,229,$n$Though he fall, he shall not be utterly cast down — the catching hand$n$,$n$Psalm 37:24 — *he shall not be utterly cast down: for Yahuah (LORD) upholdeth him with his hand.* The just man's rising after the fall is Yahuah (LORD) holding him up with his hand.$n$),
(2411,'canon','proverbs',24,16,$n$For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.$n$,'canon','psalms',145,14,$n$thread:effort-over-accomplishment | Upholdeth all that fall, raiseth up all those that be bowed down$n$,$n$Psalm 145:14 — *Yahuah (LORD) upholdeth all that fall, and raiseth up all those that be bowed down.* *For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.* (Proverbs 24:16) Seven falls and he rises. The psalm says who does the raising: Yahuah (LORD) *upholdeth all that fall*, and lifts those who are *bowed down*. The bowed head is not thrown away. It is the very one he lifts, which fits the head that goes lower the more mercy it sees.$n$,229,$n$Upholdeth all that fall, raiseth up all those that be bowed down$n$,$n$Psalm 145:14 — *upholdeth all that fall, and raiseth up all those that be bowed down.* Yahuah (LORD) lifts the ones who fall and the ones bowed low, so the fall is not the end.$n$),
(2412,'canon','proverbs',24,16,$n$For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.$n$,'canon','ezekiel',36,26,$n$thread:effort-over-accomplishment | The new heart is the heart that rises; falling is not the verdict, refusing to rise is$n$,$n$Ezekiel 36:26 — *A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.* *For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.* (Proverbs 24:16) The new heart is the heart that rises. Adonai Yahuah (the Lord GOD) takes out the *stony heart* and gives *an heart of flesh*, and a heart of flesh is one that can fall, feel it, and get up again. The stopped ear is the stone. Falling is not the verdict. Refusing to rise is.$n$,229,$n$The new heart is the heart that rises; falling is not the verdict, refusing to rise is$n$,$n$Ezekiel 36:26 — *I will take away the stony heart out of your flesh, and I will give you an heart of flesh.* The heart of flesh given in place of stone is the heart that rises after it falls.$n$),
(2409,'canon','proverbs',24,16,$n$For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.$n$,'canon','micah',7,8,$n$thread:effort-over-accomplishment | When I fall, I shall arise — the just-man-rises in prophetic register$n$,$n$Micah 7:8 — *Rejoice not against me, O mine enemy: when I fall, I shall arise; when I sit in darkness, Yahuah (LORD) shall be a light unto me.* *For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.* (Proverbs 24:16) Micah puts the proverb in the first person: *when I fall, I shall arise*. He sits in darkness and Yahuah (LORD) is his light. He does not claim he never fell, and a verse later he owns that he sinned. What makes him just is that he rises toward the light and does not stop his ears.$n$,229,$n$When I fall, I shall arise — the just-man-rises in prophetic register$n$,$n$Micah 7:8 — *when I fall, I shall arise; when I sit in darkness, Yahuah (LORD) shall be a light unto me.* The prophet speaks the proverb as his own, falling and rising with Yahuah (LORD) as his light.$n$),
(2413,'canon','proverbs',24,16,$n$For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.$n$,'canon','romans',11,32,$n$thread:effort-over-accomplishment | The just fall too — concluded all in unbelief, that he might have mercy upon all$n$,$n$Romans 11:32 — *For Elohim (God) hath concluded them all in unbelief, that he might have mercy upon all.* *For a righteous man falls seven times, and rises up again: but the wicked shall fall into mischief.* (Proverbs 24:16) If the just fall too, here is why. Elohim (God) has *concluded them all in unbelief*, so that he might *have mercy upon all*. Nobody stands on a clean record. The rising comes out of mercy, given for his name's sake, and not out of anything a man accomplished.$n$,229,$n$The just fall too — concluded all in unbelief, that he might have mercy upon all$n$,$n$Romans 11:32 — *hath concluded them all in unbelief, that he might have mercy upon all.* Everyone is shut up in the fall so that the rising can be mercy and not a wage.$n$),
(2426,'canon','proverbs',28,9,$n$He that turns away his ear from hearing the law, even his prayer shall be abomination.$n$,'canon','zechariah',7,12,$n$thread:effort-over-accomplishment | Ear-turn-from-law → stopped-ears against the prophets — same heart, two registers$n$,$n$Zechariah 7:12 — *Yea, they made their hearts as an adamant stone, lest they should hear the law, and the words which Yahuah Tseva'ot (LORD of hosts) hath sent in his spirit by the former prophets: therefore came a great wrath from Yahuah Tseva'ot (LORD of hosts).* *He that turns away his ear from hearing the law, even his prayer shall be abomination.* (Proverbs 28:9) Turn the ear from the law and even the prayer is an abomination. Zechariah shows what that looks like. They made their hearts *an adamant stone*, *lest they should hear the law*. It is the stony heart Ezekiel says gets taken out. The stopped ear and the hard heart are one thing, and the wrath came on those who would not hear.$n$,229,$n$Ear-turn-from-law → stopped-ears against the prophets — same heart, two registers$n$,$n$Zechariah 7:12 — *they made their hearts as an adamant stone, lest they should hear the law.* The wicked man's stopped ear is a heart made stone on purpose, so that the law is not heard.$n$),
(2427,'canon','proverbs',28,9,$n$He that turns away his ear from hearing the law, even his prayer shall be abomination.$n$,'canon','acts',7,57,$n$thread:effort-over-accomplishment | Ear-turn-from-law → NT narrative of stopped-ears at Stephen$n$,$n$Acts 7:57 — *Then they cried out with a loud voice, and stopped their ears, and ran upon him with one accord,* *He that turns away his ear from hearing the law, even his prayer shall be abomination.* (Proverbs 28:9) Stephen says he sees the Son of Adam standing at the right hand of Elohim (God), and the crowd *stopped their ears* and ran at him. That is the proverb walking about in daylight. The ear is turned from what is said, and the answer to it is violence. The wicked does not fall and rise. He shuts his ears and runs.$n$,229,$n$Ear-turn-from-law → NT narrative of stopped-ears at Stephen$n$,$n$Acts 7:57 — *they cried out with a loud voice, and stopped their ears, and ran upon him with one accord.* The crowd that stops its ears at Stephen is the wicked man of the proverb, turning from what he is told.$n$),
(2448,'canon','ecclesiastes',7,20,$n$For there is not a just man upon earth, that does good, and sins not.$n$,'canon','romans',3,23,$n$thread:effort-over-accomplishment | Wisdom's verdict → Paul's NT restatement$n$,$n$Romans 3:23 — *For all have sinned, and come short of the glory of Elohim (God);* *For there is not a just man upon earth, that does good, and sins not.* (Ecclesiastes 7:20) The preacher says no just man on earth does good and never sins. Paul says it wider: *all have sinned*, and every one falls short of Elohim (God). The fall belongs to everyone, so it cannot be what separates the just from the wicked. The difference has to come after.$n$,229,$n$Wisdom's verdict → Paul's NT restatement$n$,$n$Romans 3:23 — *all have sinned, and come short of the glory of Elohim (God).* Paul widens the preacher's verdict to all, so the fall is common ground and not the dividing line.$n$),
(2433,'canon','isaiah',6,5,$n$Then said I, Woe is me! for I am undone; because I am a man of unclean lips, and I dwell in the midst of a people of unclean lips: for my eyes have seen the King, Yahuah Tseva'ot (LORD of hosts).$n$,'canon','ezekiel',36,31,$n$thread:effort-over-accomplishment | Woe is me = loathe yourselves — prophetic hanging head$n$,$n$Ezekiel 36:31 — *Then shall ye remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* *Then said I, Woe is me! for I am undone; because I am a man of unclean lips, and I dwell in the midst of a people of unclean lips: for my eyes have seen the King, Yahuah Tseva'ot (LORD of hosts).* (Isaiah 6:5) Isaiah sees Yahuah (LORD) and cries *woe is me*, undone and unclean. Ezekiel says what the gathered house does under the new heart: *lothe yourselves in your own sight*. It is the same hanging head. The nearer a man gets to the holy one, the lower he goes.$n$,229,$n$Woe is me = loathe yourselves — prophetic hanging head$n$,$n$Ezekiel 36:31 — *remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight.* The new heart remembers its own evil ways and loathes itself, the same low cry Isaiah gave before the holy one.$n$),
(2440,'canon','isaiah',41,22,$n$Let them bring them forth, and shew us what shall happen: let them shew the former things, what they be, that we may consider them, and know the latter end of them; or declare us things for to come.$n$,'canon','isaiah',46,10,$n$thread:effort-over-accomplishment | Challenge to the gods → the Most High's own answer$n$,$n$Isaiah 46:10 — *Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:* *Let them bring them forth, and shew us what shall happen: let them shew the former things, what they be, that we may consider them, and know the latter end of them; or declare us things for to come.* (Isaiah 41:22) In the earlier chapter the idols are told to *shew the former things* and say what is to come, and they cannot. Here Yahuah (LORD) does it himself: *declaring the end from the beginning*, and his counsel stands. What he named before it happened cannot be turned by any man's effort or failure. The end he named is the gathering.$n$,229,$n$Challenge to the gods → the Most High's own answer$n$,$n$Isaiah 46:10 — *the end from the beginning, and from ancient times the things that are not yet done.* Only the one who declares the end from the beginning can answer the challenge, so the end he named stands.$n$),
(2441,'canon','isaiah',46,9,$n$Remember the former things of old: for I am Elohim (God), and there is none else; I am Elohim (God), and there is none like me,$n$,'canon','isaiah',41,21,$n$thread:effort-over-accomplishment | There is none else → produce your cause$n$,$n$Isaiah 41:21 — *Produce your cause, saith Yahuah (LORD); bring forth your strong reasons, saith the King of Jacob.* *Remember the former things of old: for I am Elohim (God), and there is none else; I am Elohim (God), and there is none like me,* (Isaiah 46:9) Yahuah (LORD) says *there is none else* and *none like me*. In the earlier chapter he lays down the same claim as a challenge: *produce your cause*, bring your reasons. Anyone who would be Elohim (God) beside him must answer what he has declared. Nobody does, and so his counsel stands.$n$,229,$n$There is none else → produce your cause$n$,$n$Isaiah 41:21 — *bring forth your strong reasons, saith the King of Jacob.* The challenge to bring forth reasons is the other side of his claim that there is none like him.$n$),
(2438,'canon','isaiah',46,10,$n$Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:$n$,'canon','isaiah',48,3,$n$thread:effort-over-accomplishment | Declaring the end → I have declared the former things — same self-witness$n$,$n$Isaiah 48:3 — *I have declared the former things from the beginning; and they went forth out of my mouth, and I shewed them; I did them suddenly, and they came to pass.* *Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:* (Isaiah 46:10) He declared the end, and he also says he declared the *former things from the beginning*. They went out of his mouth, he did them, and they came to pass. What he spoke, he has done before. So the end he declared will come the same way, and it does not hang on how well the house walked.$n$,229,$n$Declaring the end → I have declared the former things — same self-witness$n$,$n$Isaiah 48:3 — *I have declared the former things from the beginning; and they went forth out of my mouth.* What he declared before has already come to pass, which is the record behind the end he declares.$n$),
(2439,'canon','isaiah',48,3,$n$I have declared the former things from the beginning; and they went forth out of my mouth, and I shewed them; I did them suddenly, and they came to pass.$n$,'canon','isaiah',46,10,$n$thread:effort-over-accomplishment | Before it came to pass I shewed it thee — the declaration confirmed$n$,$n$Isaiah 46:10 — *Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:* *I have declared the former things from the beginning; and they went forth out of my mouth, and I shewed them; I did them suddenly, and they came to pass.* (Isaiah 48:3) He did the former things as he said he would. Now see where the same voice points: *declaring the end from the beginning*, and *My counsel shall stand*. What he has already done is the pledge of what he has declared. The end stands because the one who said it has kept his word before.$n$,229,$n$Before it came to pass I shewed it thee — the declaration confirmed$n$,$n$Isaiah 46:10 — *My counsel shall stand, and I will do all my pleasure.* His counsel stands because what he declared earlier has already come to pass.$n$),
(2443,'canon','isaiah',48,9,$n$For my name’s sake will I defer my anger, and for my praise will I refrain for you, that I cut you not off.$n$,'canon','psalms',25,11,$n$thread:effort-over-accomplishment | For mine own sake → David's prayer in the same posture$n$,$n$Psalm 25:11 — *For thy name’s sake, O Yahuah (LORD), pardon mine iniquity; for it is great.* *For my name’s sake will I defer my anger, and for my praise will I refrain for you, that I cut you not off.* (Isaiah 48:9) Yahuah (LORD) says he holds back his anger for his own name's sake. David asks in the same way, *for thy name’s sake*, and gives his reason: *for it is great*. He does not plead a record. He asks pardon on the name alone. That is the new heart's posture, low and asking.$n$,229,$n$For mine own sake → David's prayer in the same posture$n$,$n$Psalm 25:11 — *For thy name’s sake, O Yahuah (LORD), pardon mine iniquity; for it is great.* David prays the same ground Yahuah (LORD) gave, the name's sake, and brings only his great iniquity.$n$),
(2419,'canon','ezekiel',18,24,$n$But when the righteous turns away from his righteousness, and commits iniquity, and does according to all the abominations that the wicked man does, shall he live? All his righteousness that he has done shall not be mentioned: in his trespass that he has trespassed, and in his sin that he has sinned, in them shall he die.$n$,'canon','matthew',7,23,$n$thread:effort-over-accomplishment | Righteous turning away → I never knew you — same architecture, NT vocabulary$n$,$n$Matthew 7:23 — *And then will I profess unto them, I never knew you: depart from me, ye that work iniquity.* *But when the righteous turns away from his righteousness, and commits iniquity, and does according to all the abominations that the wicked man does, shall he live? All his righteousness that he has done shall not be mentioned: in his trespass that he has trespassed, and in his sin that he has sinned, in them shall he die.* (Ezekiel 18:24) Ezekiel says that when the righteous turns away and does the abominations, his righteousness *shall not be mentioned*. Yahusha (Jesus) says it again at the end, and those who hear *depart from me* had prophesied and done wonders in his name. Their past works carried nobody. The one who promised the new heart is the one who says it.$n$,229,$n$Righteous turning away → I never knew you — same architecture, NT vocabulary$n$,$n$Matthew 7:23 — *I never knew you: depart from me, ye that work iniquity.* The one who gives the new heart also tells the works of iniquity to depart, as Ezekiel had said.$n$),
(2437,'canon','ezekiel',20,43,$n$And there shall you remember your ways, and all your doings, wherein you have been defiled; and you shall lothe yourselves in your own sight for all your evils that you have committed.$n$,'canon','ezekiel',36,31,$n$thread:effort-over-accomplishment | Companion verse within Ezekiel — the hanging head twice named$n$,$n$Ezekiel 36:31 — *Then shall ye remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* *And there shall you remember your ways, and all your doings, wherein you have been defiled; and you shall lothe yourselves in your own sight for all your evils that you have committed.* (Ezekiel 20:43) Ezekiel says it twice. Both times the house remembers its ways and will *lothe yourselves in your own sight*. The hanging head is named once and then named again beside the new heart. It is not a stage the gathered grow out of. It is how they stand before the one who gathered them.$n$,229,$n$Companion verse within Ezekiel — the hanging head twice named$n$,$n$Ezekiel 36:31 — *shall lothe yourselves in your own sight for your iniquities and for your abominations.* The loathing of self is named a second time in Ezekiel, now beside the cleansing and the new heart.$n$),
(2420,'canon','ezekiel',33,13,$n$When I shall say to the righteous, that he shall surely live; if he trust to his own righteousness, and commit iniquity, all his righteousnesses shall not be remembered; but for his iniquity that he has committed, he shall die for it.$n$,'canon','ezekiel',18,24,$n$thread:effort-over-accomplishment | If he trust to his own righteousness, and commit iniquity — Ezekiel's twin warning$n$,$n$Ezekiel 18:24 — *But when the righteous turneth away from his righteousness, and committeth iniquity, and doeth according to all the abominations that the wicked man doeth, shall he live? All his righteousness that he hath done shall not be mentioned: in his trespass that he hath trespassed, and in his sin that he hath sinned, in them shall he die.* *When I shall say to the righteous, that he shall surely live; if he trust to his own righteousness, and commit iniquity, all his righteousnesses shall not be remembered; but for his iniquity that he has committed, he shall die for it.* (Ezekiel 33:13) Both verses give the same warning. The righteous who trusts his own righteousness and commits iniquity does not live on what he did before. Here the turning is spelled out: he *doeth according to all the abominations*, and his righteousness is not mentioned. A man's past works do not carry him. The turning does.$n$,229,$n$If he trust to his own righteousness, and commit iniquity — Ezekiel's twin warning$n$,$n$Ezekiel 18:24 — *All his righteousness that he hath done shall not be mentioned: in his trespass that he hath trespassed.* The righteous man who turns away loses the standing his earlier righteousness gave him.$n$),
(2418,'canon','ezekiel',36,27,$n$And I will put my spirit within you, and cause you to walk in my statutes, and you shall keep my judgments, and do them.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | The new heart causes the walking; the walking includes the rising after the fall$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *And I will put my spirit within you, and cause you to walk in my statutes, and you shall keep my judgments, and do them.* (Ezekiel 36:27) His spirit put within them *cause you to walk in my statutes*, and keep his judgments. The proverb shows what that walking looks like. The just man falls seven times and rises. Walking in Torah is not a straight line. It is getting up again. The one who stops his ears stays where he fell.$n$,229,$n$The new heart causes the walking; the walking includes the rising after the fall$n$,$n$Proverbs 24:16 — *a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* The walking that the new heart causes includes rising again after the fall, and the wicked does not rise.$n$),
(2414,'canon','ezekiel',36,31,$n$Then shall you remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.$n$,'canon','job',42,6,$n$thread:effort-over-accomplishment | I abhor myself — Job's hanging head matches loathe-yourselves$n$,$n$Job 42:6 — *Wherefore I abhor myself, and repent in dust and ashes.* *Then shall you remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* (Ezekiel 36:31) Job says it in one line: *I abhor myself*, and he sits in dust and ashes. It is the loathing Ezekiel gives the gathered house. Job had just said his eye now saw Yahuah (LORD), and the sight lowered him. The new heart goes lower the more mercy it sees.$n$,229,$n$I abhor myself — Job's hanging head matches loathe-yourselves$n$,$n$Job 42:6 — *Wherefore I abhor myself, and repent in dust and ashes.* Job's abhorring of himself in dust and ashes is the same hanging head as loathing yourselves.$n$),
(2415,'canon','ezekiel',36,31,$n$Then shall you remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.$n$,'canon','isaiah',6,5,$n$thread:effort-over-accomplishment | Woe is me, I am undone — the prophet's hanging head in commissioning vision$n$,$n$Isaiah 6:5 — *Then said I, Woe is me! for I am undone; because I am a man of unclean lips, and I dwell in the midst of a people of unclean lips: for mine eyes have seen the King, Yahuah Tseva'ot (LORD of hosts).* *Then shall you remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* (Ezekiel 36:31) Ezekiel says the new heart will loathe itself. Isaiah is that heart in the room. He sees Yahuah (LORD) and does not stand up straighter. He says *Woe is me* and calls himself *undone*. The sight of holiness lowers his head, and the coal that cleans him comes after.$n$,229,$n$Woe is me, I am undone — the prophet's hanging head in commissioning vision$n$,$n$Isaiah 6:5 — *Woe is me! for I am undone; because I am a man of unclean lips.* Isaiah sees the holy one and loathes himself first, the same lowered head the new heart is promised.$n$),
(2417,'canon','ezekiel',36,31,$n$Then shall you remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.$n$,'canon','ezekiel',20,43,$n$thread:effort-over-accomplishment | Companion passage within Ezekiel — the hanging head twice named$n$,$n$Ezekiel 20:43 — *And there shall ye remember your ways, and all your doings, wherein ye have been defiled; and ye shall lothe yourselves in your own sight for all your evils that ye have committed.* *Then shall you remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* (Ezekiel 36:31) Ezekiel says it twice, so it is no slip of the pen. Gathered out of the countries and brought home, the house of Yashar'el (Israel) will *remember* their ways and loathe themselves. The homecoming does not wipe out the memory. The mercy that brings them back is what lets them see what they were.$n$,229,$n$Companion passage within Ezekiel — the hanging head twice named$n$,$n$Ezekiel 20:43 — *ye shall lothe yourselves in your own sight for all your evils.* Even in the land, even gathered home, the house is told it will loathe itself in its own sight.$n$),
(2416,'canon','ezekiel',36,31,$n$Then shall you remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.$n$,'canon','daniel',9,5,$n$thread:effort-over-accomplishment | Daniel's confession of fathers' sins matches the same posture$n$,$n$Daniel 9:5 — *We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from thy precepts and from thy judgments:* *Then shall you remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* (Ezekiel 36:31) Here is the loathing in a man's own mouth. Daniel does not defend himself or his fathers. He piles the words up, *sinned*, *iniquity*, *wickedly*, *rebelled*, and he says *we*, counting himself in. The new heart Ezekiel promises sounds like this prayer.$n$,229,$n$Daniel's confession of fathers' sins matches the same posture$n$,$n$Daniel 9:5 — *We have sinned, and have committed iniquity, and have done wickedly.* Daniel prays the loathing out loud, naming every failure and counting himself among those who failed.$n$),
(2434,'canon','daniel',9,5,$n$We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from your precepts and from your judgments:$n$,'canon','leviticus',26,40,$n$thread:effort-over-accomplishment | Daniel confessing fathers' sins fulfills the Leviticus pattern$n$,$n$Leviticus 26:40 — *If they shall confess their iniquity, and the iniquity of their fathers, with their trespass which they trespassed against me, and that also they have walked contrary unto me;* *We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from your precepts and from your judgments:* (Daniel 9:5) Daniel's prayer is what Leviticus told them to pray. Long before the exile the way back was laid out: confess their own iniquity and *the iniquity of their fathers*. Daniel does exactly that, he and his people together, and the Torah he prays out of has not moved. The confession is the road home, and it was in the law first.$n$,229,$n$Daniel confessing fathers' sins fulfills the Leviticus pattern$n$,$n$Leviticus 26:40 — *If they shall confess their iniquity, and the iniquity of their fathers.* Leviticus names confessing the iniquity of the fathers as the way back, and Daniel walks it.$n$),
(2435,'canon','daniel',9,5,$n$We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from your precepts and from your judgments:$n$,'canon','ezekiel',36,31,$n$thread:effort-over-accomplishment | Daniel hangs his head — the new heart's response in restoration prayer$n$,$n$Ezekiel 36:31 — *Then shall ye remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* *We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from your precepts and from your judgments:* (Daniel 9:5) Daniel prays it, Ezekiel promises it. The man on his face in confession is the man Ezekiel describes, who will *remember* his evil ways and *lothe yourselves* before his own eyes. Neither one is boasting of what he has done. The same chapter that promises the heart says the heart will hang its head, and Daniel is already doing it.$n$,229,$n$Daniel hangs his head — the new heart's response in restoration prayer$n$,$n$Ezekiel 36:31 — *shall lothe yourselves in your own sight for your iniquities.* The promised new heart loathes itself in its own sight, which is what Daniel's confession already sounds like.$n$),
(2431,'canon','hosea',4,6,$n$My people are destroyed for lack of knowledge: because you have rejected knowledge, I will also reject you, that you shall be no priest to me: seeing you have forgotten the law of your Elohim (God), I will also forget your children.$n$,'canon','proverbs',28,9,$n$thread:effort-over-accomplishment | Rejected knowledge = ear-turn-from-law — the wicked heart's self-identification$n$,$n$Proverbs 28:9 — *He that turneth away his ear from hearing the law, even his prayer shall be abomination.* *My people are destroyed for lack of knowledge: because you have rejected knowledge, I will also reject you, that you shall be no priest to me: seeing you have forgotten the law of your Elohim (God), I will also forget your children.* (Hosea 4:6) Hosea says they were destroyed because they *rejected knowledge* and *forgotten the law*. Proverbs shows what that looks like in one man. He turns his ear away from the law, and even his prayer becomes an abomination. This is the wicked side of the line. He is not marked out by his falling but by the ear he will not give.$n$,229,$n$Rejected knowledge = ear-turn-from-law — the wicked heart's self-identification$n$,$n$Proverbs 28:9 — *He that turneth away his ear from hearing the law.* The man who turns his ear from the law is the one Hosea says rejected knowledge, and his prayer goes with it.$n$),
(2428,'canon','zechariah',7,11,$n$But they refused to hearken, and pulled away the shoulder, and stopped their ears, that they should not hear.$n$,'canon','acts',7,57,$n$thread:effort-over-accomplishment | The pattern of the fathers → the pattern at Stephen's stoning$n$,$n$Acts 7:57 — *Then they cried out with a loud voice, and stopped their ears, and ran upon him with one accord,* *But they refused to hearken, and pulled away the shoulder, and stopped their ears, that they should not hear.* (Zechariah 7:11) Zechariah told what the fathers did. They *stopped their ears, that they should not hear*. When Stephen says he sees the Son of Adam standing, his hearers cry out and *stopped their ears* too, then run at him together. The old refusal did not end with the fathers. The ear that will not hear is the sign of the wicked in both places.$n$,229,$n$The pattern of the fathers → the pattern at Stephen's stoning$n$,$n$Acts 7:57 — *Then they cried out with a loud voice, and stopped their ears.* Stephen's hearers stop their ears the way the fathers did, which is the wicked man's answer to being told.$n$),
(2429,'canon','zechariah',7,12,$n$Yea, they made their hearts as an adamant stone, lest they should hear the law, and the words which Yahuah Tseva'ot (LORD of hosts) has sent in his spirit by the former prophets: therefore came a great wrath from Yahuah Tseva'ot (LORD of hosts).$n$,'canon','proverbs',28,9,$n$thread:effort-over-accomplishment | Stopped ears = ear-turn-from-law in wisdom register$n$,$n$Proverbs 28:9 — *He that turneth away his ear from hearing the law, even his prayer shall be abomination.* *Yea, they made their hearts as an adamant stone, lest they should hear the law, and the words which Yahuah Tseva'ot (LORD of hosts) has sent in his spirit by the former prophets: therefore came a great wrath from Yahuah Tseva'ot (LORD of hosts).* (Zechariah 7:12) Zechariah says they made their hearts *an adamant stone* so as not to hear the law. Proverbs gives the cost. The one who turns his ear from the law finds *even his prayer* has become *abomination*. The stone heart is the opposite of the heart of flesh that is promised. It is the wicked man shutting what the just man opens.$n$,229,$n$Stopped ears = ear-turn-from-law in wisdom register$n$,$n$Proverbs 28:9 — *turneth away his ear from hearing the law, even his prayer shall be abomination.* Turning the ear from the law ruins even the prayer, the same refusal Zechariah calls a heart of stone.$n$),
(2423,'canon','matthew',7,21,$n$Not every one that says unto me, Lord, Lord, shall enter into the kingdom of heaven; but he that does the will of my Father which is in heaven.$n$,'canon','ezekiel',36,27,$n$thread:effort-over-accomplishment | Doing the will of the Father = walking in the statutes the new heart was given to walk$n$,$n$Ezekiel 36:27 — *And I will put my spirit within you, and cause you to walk in my statutes, and ye shall keep my judgments, and do them.* *Not every one that says unto me, Lord, Lord, shall enter into the kingdom of heaven; but he that does the will of my Father which is in heaven.* (Matthew 7:21) Yahusha (Jesus) says it is not the one who says *Adonai* but *he that doeth the will of my Father* who enters. Ezekiel shows what that will is and how it comes to be done. Yahuah (LORD) puts his own spirit within and causes them to walk in his statutes, and they *keep my judgments, and do them*. The gift is what makes the doing possible, and the doing is still asked.$n$,229,$n$Doing the will of the Father = walking in the statutes the new heart was given to walk$n$,$n$Ezekiel 36:27 — *cause you to walk in my statutes, and ye shall keep my judgments, and do them.* The new heart is given so that the statutes are walked and kept, so the gift and the doing are one promise.$n$),
(2424,'canon','matthew',7,23,$n$And then will I profess unto them, I never knew you: depart from me, you that work iniquity.$n$,'canon','ezekiel',18,24,$n$thread:effort-over-accomplishment | Depart from me ← the righteousness that turned away does not deliver$n$,$n$Ezekiel 18:24 — *But when the righteous turneth away from his righteousness, and committeth iniquity, and doeth according to all the abominations that the wicked man doeth, shall he live? All his righteousness that he hath done shall not be mentioned: in his trespass that he hath trespassed, and in his sin that he hath sinned, in them shall he die.* *And then will I profess unto them, I never knew you: depart from me, you that work iniquity.* (Matthew 7:23) Why would Yahusha (Jesus) say *depart from me* to people who used his name? Ezekiel has already said how it goes. The righteous man who turns away and *committeth iniquity* finds that what he did before does not carry him. A name spoken is not a heart kept, and the ones sent away are the ones *that work iniquity*.$n$,229,$n$Depart from me ← the righteousness that turned away does not deliver$n$,$n$Ezekiel 18:24 — *All his righteousness that he hath done shall not be mentioned.* Righteousness done before the turning away is not counted to the man who turns, which is why he is sent away.$n$),
(2425,'canon','matthew',7,23,$n$And then will I profess unto them, I never knew you: depart from me, you that work iniquity.$n$,'canon','revelation',3,5,$n$thread:effort-over-accomplishment | Depart from me / blot out his name — the post-harvest sifting of wheat$n$,$n$Revelation 3:5 — *He that overcometh, the same shall be clothed in white raiment; and I will not blot out his name out of the book of life, but I will confess his name before my Father, and before his angels.* *And then will I profess unto them, I never knew you: depart from me, you that work iniquity.* (Matthew 7:23) The same Yahusha (Jesus) who says *depart from me* says here *I will not blot out his name*, and he says it to the one who overcomes, clothed in white. So a name can be blotted out and a name can be kept. Those are two sides of one door. The overcomer keeps the walk and the name stays. The one sent away is not confessed before the Father.$n$,229,$n$Depart from me / blot out his name — the post-harvest sifting of wheat$n$,$n$Revelation 3:5 — *I will not blot out his name out of the book of life.* A name can be blotted from the book of life, and the overcomer's is the one that stays.$n$),
(2430,'canon','acts',7,57,$n$Then they cried out with a loud voice, and stopped their ears, and ran upon him with one accord,$n$,'canon','zechariah',7,11,$n$thread:effort-over-accomplishment | The hearers continue the fathers' refusal — Stephen names it and they confirm it$n$,$n$Zechariah 7:11 — *But they refused to hearken, and pulled away the shoulder, and stopped their ears, that they should not hear.* *Then they cried out with a loud voice, and stopped their ears, and ran upon him with one accord,* (Acts 7:57) Stephen's hearers stopped their ears and ran at him. Zechariah shows where they learned it. The fathers *refused to hearken* and *pulled away the shoulder*, and their children do the same thing with their hands. It is the wicked man's answer, not a fall but a refusal to be told.$n$,229,$n$The hearers continue the fathers' refusal — Stephen names it and they confirm it$n$,$n$Zechariah 7:11 — *But they refused to hearken, and pulled away the shoulder, and stopped their ears.* The fathers refused to hear and stopped their ears, and Stephen's hearers repeat it exactly.$n$),
(2454,'canon','acts',17,30,$n$And the times of this ignorance Elohim (God) winked at; but now commands all men every where to repent:$n$,'canon','romans',1,20,$n$thread:effort-over-accomplishment | Winked at ignorance, now commands repent — the witness made plain$n$,$n$Romans 1:20 — *For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:* *And the times of this ignorance Elohim (God) winked at; but now commands all men every where to repent:* (Acts 17:30) Elohim (God) *winked at* the times of ignorance, and now he commands every man to repent. Paul in Romans shows why ignorance is no wall to hide behind. What the maker is, his *eternal power*, is *clearly seen* in what he made, *so that they are without excuse*. The call to repent goes to everyone because everyone could see.$n$,229,$n$Winked at ignorance, now commands repent — the witness made plain$n$,$n$Romans 1:20 — *the invisible things of him from the creation of the world are clearly seen.* What can be seen in the creation is why the call to repent leaves no one with an excuse.$n$),
(2451,'canon','romans',1,20,$n$For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:$n$,'canon','psalms',19,1,$n$thread:effort-over-accomplishment | Without excuse — the heavens declare the glory$n$,$n$Psalm 19:1 — *The heavens declare the glory of Elohim (God); and the firmament sheweth his handywork.* *For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:* (Romans 1:20) Paul says the maker's power is *clearly seen* in what he made. The psalm sang it first. *The heavens declare the glory* of Elohim (God), and the firmament shows his handiwork. Nothing new is added. The sky was already speaking, so the man who stops his ears has nothing to blame but the ears.$n$,229,$n$Without excuse — the heavens declare the glory$n$,$n$Psalm 19:1 — *The heavens declare the glory of Elohim (God); and the firmament sheweth his handywork.* The heavens already declare the glory of Elohim (God), which is the witness Paul says leaves men without excuse.$n$),
(2453,'canon','romans',2,15,$n$Which shew the work of the law written in their hearts, their conscience also bearing witness, and their thoughts the mean while accusing or else excusing one another;)$n$,'canon','jeremiah',31,33,$n$thread:effort-over-accomplishment | Law written in hearts — the new-covenant interior witness$n$,$n$Jeremiah 31:33 — *But this shall be the covenant that I will make with the house of Yashar'el (Israel); After those days, saith Yahuah (LORD), I will put my law in their inward parts, and write it in their hearts; and will be their Elohim (God), and they shall be my people.* *Which shew the work of the law written in their hearts, their conscience also bearing witness, and their thoughts the mean while accusing or else excusing one another;)* (Romans 2:15) Paul sees *the work of the law written in their hearts*. Jeremiah says where that writing comes from and whose law it is. Yahuah (LORD) tells the house of Yashar'el (Israel) that he will *put my law in their inward parts*. It is the same law, Torah, not a new one, and the new covenant is that law on the heart. What Paul sees at work is what Jeremiah promised.$n$,229,$n$Law written in hearts — the new-covenant interior witness$n$,$n$Jeremiah 31:33 — *I will put my law in their inward parts, and write it in their hearts.* The new covenant is the law itself written on the heart, which is what Paul sees working inside.$n$),
(2444,'canon','romans',3,10,$n$As it is written, There is none righteous, no, not one:$n$,'canon','psalms',14,1,$n$thread:effort-over-accomplishment | Paul quoting Psalm 14 — the leveling baseline$n$,$n$Psalm 14:1 — *The fool hath said in his heart, There is no Elohim (God). They are corrupt, they have done abominable works, there is none that doeth good.* *As it is written, There is none righteous, no, not one:* (Romans 3:10) Paul writes *There is none righteous* and says *as it is written*. This is where. The psalm says the fool's heart says there is no Elohim (God), and then *there is none that doeth good*. It puts every man on the same ground before anyone can boast, which is why the line between just and wicked cannot be drawn at the fall.$n$,229,$n$Paul quoting Psalm 14 — the leveling baseline$n$,$n$Psalm 14:1 — *They are corrupt, they have done abominable works, there is none that doeth good.* The psalm levels every man on the same ground, so the just are not the ones who never fell.$n$),
(2445,'canon','romans',3,23,$n$For all have sinned, and come short of the glory of Elohim (God);$n$,'canon','1-kings',8,46,$n$thread:effort-over-accomplishment | All have sinned ← Solomon's no man sinneth not$n$,$n$1 Kings 8:46 — *If they sin against thee, (for there is no man that sinneth not,) and thou be angry with them, and deliver them to the enemy, so that they carry them away captives unto the land of the enemy, far or near;* *For all have sinned, and come short of the glory of Elohim (God);* (Romans 3:23) Paul's *all have sinned* is no new charge. Solomon said it at the dedication of the house: *there is no man that sinneth not*. He said it as the ground for asking mercy, because a people that sin will be carried away captive, and a people that bethink themselves and repent can come home. The fall is expected. What follows it is what counts.$n$,229,$n$All have sinned ← Solomon's no man sinneth not$n$,$n$1 Kings 8:46 — *for there is no man that sinneth not.* Solomon names the universal sin as the ground for repenting and coming home, long before Paul.$n$),
(2446,'canon','romans',11,32,$n$For Elohim (God) has concluded them all in unbelief, that he might have mercy upon all.$n$,'canon','galatians',3,22,$n$thread:effort-over-accomplishment | Concluded all in unbelief ↔ concluded all under sin — same architecture, two letters$n$,$n$Galatians 3:22 — *But the scripture hath concluded all under sin, that the promise by faith of Yahusha HaMashiach (Jesus Christ) might be given to them that believe.* *For Elohim (God) has concluded them all in unbelief, that he might have mercy upon all.* (Romans 11:32) Two letters, one sentence. Romans says Elohim (God) *concluded them all in unbelief*, and Galatians says the scripture *concluded all under sin*. Both shut the door on boasting and open it on mercy and the promise. Galatians does not set the law against the promises either. The verse just before asks that very thing and answers no.$n$,229,$n$Concluded all in unbelief ↔ concluded all under sin — same architecture, two letters$n$,$n$Galatians 3:22 — *the scripture hath concluded all under sin, that the promise by faith of Yahusha HaMashiach (Jesus Christ) might be given.* Everyone is shut up under sin so that the promise is given as mercy, not earned as a wage.$n$),
(2455,'canon','james',2,17,$n$Even so faith, if it has not works, is dead, being alone.$n$,'canon','matthew',7,23,$n$thread:effort-over-accomplishment | Faith without works dead → workers of iniquity who claimed his name$n$,$n$Matthew 7:23 — *And then will I profess unto them, I never knew you: depart from me, ye that work iniquity.* *Even so faith, if it has not works, is dead, being alone.* (James 2:17) James says faith with no works is *dead, being alone*. Here is what that looks like. The ones Yahusha (Jesus) sends away have used his name, prophesied and cast out devils, and he still says *I never knew you*. A name spoken with no walk behind it is a dead thing. They *work iniquity*, and the Torah that iniquity breaks is still standing.$n$,229,$n$Faith without works dead → workers of iniquity who claimed his name$n$,$n$Matthew 7:23 — *I never knew you: depart from me, ye that work iniquity.* Those who claimed the name yet worked iniquity are the dead faith James describes, and they are sent away.$n$),
(2456,'canon','james',2,26,$n$For as the body without the spirit is dead, so faith without works is dead also.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | Faith without works dead = the heart that does not rise after the fall$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *For as the body without the spirit is dead, so faith without works is dead also.* (James 2:26) James says faith without works is dead, like a body without the spirit. The proverb shows what living faith does. It falls and *riseth up again*. Not the man who never fell, but the one who gets up. The wicked man *shall fall into mischief* and stay there. The works James asks for are the rising.$n$,229,$n$Faith without works dead = the heart that does not rise after the fall$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again.* Living faith is the just man's rising after each fall, and dead faith is the one that stays down.$n$),
(2450,'canon','1-john',1,8,$n$If we say that we have no sin, we deceive ourselves, and the truth is not in us.$n$,'canon','romans',3,23,$n$thread:effort-over-accomplishment | If we say we have no sin → all have sinned$n$,$n$Romans 3:23 — *For all have sinned, and come short of the glory of Elohim (God);* *If we say that we have no sin, we deceive ourselves, and the truth is not in us.* (1 John 1:8) John says the man who claims to have *no sin* only *deceive ourselves*. Paul gives the reason, *all have sinned*, and adds that they *come short of the glory*. So the man who denies the fall is lying to himself. The just man is the one who admits it and rises. Nobody has a record clean enough to hold his head up on.$n$,229,$n$If we say we have no sin → all have sinned$n$,$n$Romans 3:23 — *For all have sinned, and come short of the glory of Elohim (God).* Everyone has sinned, so denying it is self deceit and the only honest road is confession and rising.$n$),
(2422,'canon','revelation',3,5,$n$He that overcomes, the same shall be clothed in white raiment; and I will not blot out his name out of the book of life, but I will confess his name before my Father, and before his angels.$n$,'canon','exodus',32,33,$n$thread:effort-over-accomplishment | The overcomer's name preserved — Sinai's blotting principle in NT register$n$,$n$Exodus 32:33 — *And Yahuah (LORD) said unto Moses, Whosoever hath sinned against me, him will I blot out of my book.* *He that overcomes, the same shall be clothed in white raiment; and I will not blot out his name out of the book of life, but I will confess his name before my Father, and before his angels.* (Revelation 3:5) Yahusha (Jesus) says *I will not blot out his name*, and he speaks in the light of Sinai. Yahuah (LORD) told Moses that whoever sinned against him he would *blot out of my book*. So the book is real and names can come off it. The overcomer's name stays. It is the old law of the book, not a new one, that the promise leans on.$n$,229,$n$The overcomer's name preserved — Sinai's blotting principle in NT register$n$,$n$Exodus 32:33 — *Whosoever hath sinned against me, him will I blot out of my book.* Sinai already says names are blotted out of the book, which is why keeping the name is a promise to the overcomer.$n$),
(2515,'apocrypha','2-esdras',7,46,$n$I answered then and said, This is my first and last saying, that it had been better not to have given the earth to Adam: or else, when it was given him, to have restrained him from sinning.$n$,'canon','romans',3,10,$n$thread:effort-over-accomplishment | Who is there alive that hath not sinned — the leveling baseline before Paul$n$,$n$Romans 3:10 — *As it is written, There is none righteous, no, not one:* *I answered then and said, This is my first and last saying, that it had been better not to have given the earth to Adam: or else, when it was given him, to have restrained him from sinning.* (2 Esdras 7:46) The speaker wishes it had been better *not to have given the earth to Adam*, because Adam could not be held back from sinning. Paul puts the verdict plainly: *There is none righteous, no, not one*. Both come to the same place. No one stands before the Father on a clean record, and that is where the just man's rising begins.$n$,229,$n$Who is there alive that hath not sinned — the leveling baseline before Paul$n$,$n$Romans 3:10 — *There is none righteous, no, not one.* Paul states the universal verdict plainly, the same one the speaker reaches by grieving over Adam.$n$),
(7071,'canon','luke',17,3,$n$Take heed to yourselves: If your brother trespass against you, rebuke him; and if he repent, forgive him.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *And if he trespass against thee seven times in a day, and seven times in a day turn again to thee, saying, I repent; thou shalt forgive him* (Luke 17:4). The same Elohim who says the just man falleth seven times and riseth again (Mishlei/Proverbs 24:16) also says forgive seven times in a day.$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *Take heed to yourselves: If your brother trespass against you, rebuke him; and if he repent, forgive him.* (Luke 17:3) Yahusha (Jesus) tells us to rebuke a brother who trespasses, and *if he repent, forgive him*. The proverb shows who that brother is. A *just man* falls and *riseth up again*. Repentance is the rising. The same voice gives the proverb and the forgiveness, and the next line sets the number at seven times in a day, the proverb's own number.$n$,229,$n$*And if he trespass against thee seven times in a day, and seven times in a day turn again to thee, saying, I repent; thou shalt forgive him* (Luke 17:4). The same Elohim who says the just man falleth seven times and riseth again (Mishlei/Proverbs 24:16) also says forgive seven times in a day.$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again.* The forgiven brother is the just man of the proverb, who falls and rises by repenting.$n$),
(5041,'canon','mark',4,24,$n$And he said unto them, Take heed what you hear: with what measure you mete, it shall be measured to you: and unto you that hear shall more be given.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *With what measure ye mete, it shall be measured to you: and unto you that hear shall more be given.* The hearing-leads-to-more-hearing pattern is the effort-over-accomplishment substance — *a just man falleth seven times, and riseth up again* (Mishlei/Proverbs 24:16).$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *And he said unto them, Take heed what you hear: with what measure you mete, it shall be measured to you: and unto you that hear shall more be given.* (Mark 4:24) Yahusha (Jesus) says *Take heed what ye hear*, and *unto you that hear shall more be given*. The proverb is that hearing played out in a life. The just man falls and still listens, so he rises. The wicked man falls and does not. More is given to the ear that stays open.$n$,229,$n$*With what measure ye mete, it shall be measured to you: and unto you that hear shall more be given.* The hearing-leads-to-more-hearing pattern is the effort-over-accomplishment substance — *a just man falleth seven times, and riseth up again* (Mishlei/Proverbs 24:16).$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again.* The just man's rising is hearing carried through a fall, and more is given to the one who hears.$n$),
(2514,'apocrypha','2-esdras',8,35,$n$For in truth them is no man among them that be born, but he has dealt wickedly; and among the faithful there is none which has not done amiss.$n$,'canon','romans',3,23,$n$thread:effort-over-accomplishment | No man... but he hath dealt wickedly — the universal verdict pre-Paul$n$,$n$Romans 3:23 — *For all have sinned, and come short of the glory of Elohim (God);* *For in truth them is no man among them that be born, but he has dealt wickedly; and among the faithful there is none which has not done amiss.* (2 Esdras 8:35) The writer says there is none born who has not *dealt wickedly*, and not even among the faithful is there one *which has not done amiss*. Paul puts it in one line, *all have sinned*, and adds *come short of the glory*. Same verdict. It levels everyone before the rising begins.$n$,229,$n$No man... but he hath dealt wickedly — the universal verdict pre-Paul$n$,$n$Romans 3:23 — *For all have sinned, and come short of the glory of Elohim (God).* The universal verdict that all have sinned is the baseline the just man's rising starts from.$n$),
(5148,'canon','mark',8,35,$n$For whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospel’s, the same shall save it.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *Whosoever will save his life shall lose it.* The Proverbs 24:16 *just falleth seven times and riseth up again* register names the same shape.$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *For whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospel’s, the same shall save it.* (Mark 8:35) Whoever clings to his life loses it, and whoever lets it go for the sake of Yahusha (Jesus) keeps it. The proverb walks the same road from the other end. The just man is knocked down and *riseth up again*. The wicked is the one who will not get up, and he *shall fall into mischief*.$n$,229,$n$*Whosoever will save his life shall lose it.* The Proverbs 24:16 *just falleth seven times and riseth up again* register names the same shape.$n$,$n$Proverbs 24:16 — *a just man falleth seven times, and riseth up again.* Seven falls do not end the just man because he rises each time, and that is losing a life in order to keep it.$n$),
(2517,'apocrypha','the-wisdom-of-solomon',13,8,$n$Howbeit neither are they to be pardoned.$n$,'canon','romans',1,20,$n$thread:effort-over-accomplishment | Howbeit neither are they to be pardoned — the Romans 1 argument before Romans 1$n$,$n$Romans 1:20 — *For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:* *Howbeit neither are they to be pardoned.* (Wisdom of Solomon 13:8) Both verses shut the same door. The maker was plain from what he made, so the ones who looked past him are *without excuse*. The fault is not that no witness stood in sight. The fault is ears that would not turn to it, and that is the wicked, not the just man who falls and rises.$n$,229,$n$Howbeit neither are they to be pardoned — the Romans 1 argument before Romans 1$n$,$n$Romans 1:20 — *so that they are without excuse.* Being without excuse belongs to those who had the witness in plain sight and would not hear it.$n$),
(5149,'canon','mark',8,35,$n$For whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospel’s, the same shall save it.$n$,'canon','matthew',10,39,$n$thread:effort-over-accomplishment | The Matthean parallel of the save-life-lose-life saying.$n$,$n$Matthew 10:39 — *He that findeth his life shall lose it: and he that loseth his life for my sake shall find it.* *For whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospel’s, the same shall save it.* (Mark 8:35) Same saying, said again in Matthew. The man who *findeth his life* by holding on to it loses it, and the one who gives it up for the sake of Yahusha (Jesus) *shall find it*. The loss is not in falling. The loss is in clinging to self.$n$,229,$n$The Matthean parallel of the save-life-lose-life saying.$n$,$n$Matthew 10:39 — *he that loseth his life for my sake shall find it.* Losing the life for his sake is how it is found, which is the head that goes low and then rises.$n$),
(2516,'apocrypha','the-wisdom-of-solomon',13,9,$n$For if they were able to know so much, that they could aim at the world; how did they not sooner find out Yahuah (God) thereof?$n$,'canon','romans',1,20,$n$thread:effort-over-accomplishment | How did they not sooner find out Yahuah (the Lord) — without-excuse, source argument$n$,$n$Romans 1:20 — *For the invisible things of him from the creation of the world are clearly seen, being understood by the things that are made, even his eternal power and Godhead; so that they are without excuse:* *For if they were able to know so much, that they could aim at the world; how did they not sooner find out Yahuah (God) thereof?* (Wisdom of Solomon 13:9) If men could measure so much of the world, the maker should not have been hard to find. Paul says the same plainly: what he made shows *his eternal power*, and nobody stands without a witness. Ears that hear find him. Ears stopped leave a man with no defense.$n$,229,$n$How did they not sooner find out Yahuah (the Lord) — without-excuse, source argument$n$,$n$Romans 1:20 — *the invisible things of him from the creation of the world are clearly seen.* The maker is plain from what he made, so those who still miss him do it with stopped ears, not for want of a witness.$n$),
(5150,'canon','mark',8,35,$n$For whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospel’s, the same shall save it.$n$,'canon','john',12,25,$n$thread:effort-over-accomplishment | *He that loveth his life shall lose it; and he that hateth his life in this world shall keep it unto life eternal* (Yochanan/John 12:25).$n$,$n$John 12:25 — *He that loveth his life shall lose it; and he that hateth his life in this world shall keep it unto life eternal.* *For whosoever will save his life shall lose it; but whosoever shall lose his life for my sake and the gospel’s, the same shall save it.* (Mark 8:35) John gives the same word a harder edge: *hateth his life in this world*. This is the man who stops grabbing for himself, whose head goes lower the more mercy he sees. He is not despising a gift. He is the one who *shall keep it unto life eternal*.$n$,229,$n$*He that loveth his life shall lose it; and he that hateth his life in this world shall keep it unto life eternal* (Yochanan/John 12:25).$n$,$n$John 12:25 — *he that hateth his life in this world shall keep it unto life eternal.* Hating the life that clings to itself is the lowered head, and the end of that road is life eternal.$n$),
(2518,'apocrypha','ecclesiasticus',8,5,$n$Reproach not a man that turns from sin, but remember that we are all worthy of punishment.$n$,'canon','romans',3,23,$n$thread:effort-over-accomplishment | We are all worthy of punishment — the universal verdict in wisdom register$n$,$n$Romans 3:23 — *For all have sinned, and come short of the glory of Elohim (God);* *Reproach not a man that turns from sin, but remember that we are all worthy of punishment.* (Sirach 8:5) Nobody gets to look down on a man who turns back from sin, because the same verdict sits on everyone. Paul says it flat: all have *come short*. The line between men is not drawn at the fall. It is drawn at whether a man turns, and neither writer leaves room to sneer.$n$,229,$n$We are all worthy of punishment — the universal verdict in wisdom register$n$,$n$Romans 3:23 — *For all have sinned, and come short of the glory of Elohim (God).* Everyone has come short, so what separates men is what they do after the fall, not whether they fell.$n$),
(5153,'canon','mark',8,36,$n$For what shall it profit a man, if he shall gain the whole world, and lose his own soul?$n$,'canon','psalms',49,7,$n$thread:effort-over-accomplishment | *None of them can by any means redeem his brother, nor give to Elohim (God) a ransom for him* (Tehillim/Psalm 49:7-9) — the wisdom-stream's no-exchange-value naming.$n$,$n$Psalm 49:7 — *None of them can by any means redeem his brother, nor give to Elohim (God) a ransom for him:* *For what shall it profit a man, if he shall gain the whole world, and lose his own soul?* (Mark 8:36) The man who gains the world has nothing to buy his soul back with. Those who trust their wealth cannot *by any means redeem his brother*, and no ransom is theirs to hand to Elohim (God). What a man piled up does not count. What he does with his heart does.$n$,229,$n$*None of them can by any means redeem his brother, nor give to Elohim (God) a ransom for him* (Tehillim/Psalm 49:7-9) — the wisdom-stream's no-exchange-value naming.$n$,$n$Psalm 49:7 — *None of them can by any means redeem his brother, nor give to Elohim (God) a ransom for him.* No pile of wealth buys a soul back, so the gain of the whole world answers nothing.$n$),
(2519,'apocrypha','baruch-with-the-letter-of-jeremiah',1,15,$n$And you shall say, To Yahuah (God), our Elohim (God) belongeth righteousness, but to us the confusion of faces, as it is come to pass this day, to them of Juda, and to the inhabitants of Jerusalem,$n$,'canon','daniel',9,7,$n$thread:effort-over-accomplishment | Righteousness belongeth unto thee, but unto us confusion of faces — Baruch echoes Daniel verbatim$n$,$n$Daniel 9:7 — *O Yahuah (Lord), righteousness belongeth unto thee, but unto us confusion of faces, as at this day; to the men of Yahudah (Judah), and to the inhabitants of Jerusalem, and unto all Yashar'el (Israel), that are near, and that are far off, through all the countries whither thou hast driven them, because of their trespass that they have trespassed against thee.* *And you shall say, To Yahuah (God), our Elohim (God) belongeth righteousness, but to us the confusion of faces, as it is come to pass this day, to them of Juda, and to the inhabitants of Jerusalem,* (baruch-with-the-letter-of-jeremiah 1:15) Both prayers put righteousness on one side and shame on the other. Daniel spreads it over *all Yashar'el (Israel)*, near and far, scattered through the countries where they were driven. The shame is owned and not argued away. That is the head going lower, not the ears stopping.$n$,229,$n$Righteousness belongeth unto thee, but unto us confusion of faces — Baruch echoes Daniel verbatim$n$,$n$Daniel 9:7 — *righteousness belongeth unto thee, but unto us confusion of faces, as at this day.* Righteousness is his and the confusion of faces is ours, the loathing of the new heart said aloud.$n$),
(5151,'canon','mark',8,36,$n$For what shall it profit a man, if he shall gain the whole world, and lose his own soul?$n$,'canon','matthew',16,26,$n$thread:effort-over-accomplishment | *What shall it profit a man, if he shall gain the whole world, and lose his own soul?* The Matthean parallel.$n$,$n$Matthew 16:26 — *For what is a man profited, if he shall gain the whole world, and lose his own soul? or what shall a man give in exchange for his soul?* *For what shall it profit a man, if he shall gain the whole world, and lose his own soul?* (Mark 8:36) Matthew keeps the question and adds a second one. A man who has gained the whole world is asked what he will *give in exchange for his soul*. Nothing he built can be laid on the counter. So the just man's rising is no payment. It is a heart that turns and gets up.$n$,229,$n$*What shall it profit a man, if he shall gain the whole world, and lose his own soul?* The Matthean parallel.$n$,$n$Matthew 16:26 — *what shall a man give in exchange for his soul?* Nothing a man has gained can be traded for his soul, so accomplishment cannot be the price.$n$),
(2521,'apocrypha','the-prayer-of-manasseh',1,11,$n$Now therefore I bow the knee of my heart, beseeching you of grace.$n$,'canon','ezekiel',36,31,$n$thread:effort-over-accomplishment | I have sinned, I acknowledge mine iniquities — the model return-prayer matches the new heart's loathing$n$,$n$Ezekiel 36:31 — *Then shall ye remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* *Now therefore I bow the knee of my heart, beseeching you of grace.* (the-prayer-of-manasseh 1:11) A knee that bows in the heart and begs for grace is the new heart Ezekiel names. It remembers *your own evil ways* and does not argue. The prayer asks, and the promise says what the heart will do once it is given. Mercy and loathing arrive together.$n$,229,$n$I have sinned, I acknowledge mine iniquities — the model return-prayer matches the new heart's loathing$n$,$n$Ezekiel 36:31 — *shall lothe yourselves in your own sight for your iniquities and for your abominations.* The new heart's first act is to remember its own ways and loathe itself, which is the bowed knee in a promise.$n$),
(5152,'canon','mark',8,36,$n$For what shall it profit a man, if he shall gain the whole world, and lose his own soul?$n$,'canon','luke',9,25,$n$thread:effort-over-accomplishment | The Lukan parallel.$n$,$n$Luke 9:25 — *For what is a man advantaged, if he gain the whole world, and lose himself, or be cast away?* *For what shall it profit a man, if he shall gain the whole world, and lose his own soul?* (Mark 8:36) Luke ends the question differently: a man may *lose himself, or be cast away*. The one who gains everything and loses himself is the one who never turned. Falling does not do that to a man. Refusing to rise does.$n$,229,$n$The Lukan parallel.$n$,$n$Luke 9:25 — *if he gain the whole world, and lose himself, or be cast away?* The loss named here is the man himself, which comes from refusing to turn, not from the falls along the way.$n$),
(2520,'apocrypha','the-prayer-of-manasseh',1,12,$n$I have sinned, O Yahuah (God), I have sinned, and I acknowledge my iniquities:$n$,'canon','daniel',9,5,$n$thread:effort-over-accomplishment | Forgive me, I humbly beseech thee — Manasseh's confession in Daniel-style posture$n$,$n$Daniel 9:5 — *We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from thy precepts and from thy judgments:* *I have sinned, O Yahuah (God), I have sinned, and I acknowledge my iniquities:* (the-prayer-of-manasseh 1:12) Both prayers confess in the first person and hold nothing back. Daniel's cry, *We have sinned*, is a whole people on its knees, and the other prayer says *I have sinned* for one man. Neither pleads that it did enough. That is the loathing of the new heart, in words.$n$,229,$n$Forgive me, I humbly beseech thee — Manasseh's confession in Daniel-style posture$n$,$n$Daniel 9:5 — *even by departing from thy precepts and from thy judgments.* The confession names the departure from precepts and judgments and pleads no accomplishment, only the turning back.$n$),
(5178,'canon','mark',9,24,$n$And straightway the father of the child cried out, and said with tears, Lord, I believe; help you my unbelief.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *Lord, I believe; help thou mine unbelief.* The father of the demon-possessed boy is not a man with a perfected faith — he is a man with effort. *A just man falleth seven times, and riseth up again* (Mishlei/Proverbs 24:16). **Q14 NT-Lord flag** queued for S184.$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *And straightway the father of the child cried out, and said with tears, Lord, I believe; help you my unbelief.* (Mark 9:24) The father cries out *I believe; help thou mine unbelief* with tears, and he is not turned away. He is the just man in the middle of a fall, and he is already on his way up because he cries. A man who *falleth seven times* and cries out is not the wicked, who stops his ears.$n$,229,$n$*Lord, I believe; help thou mine unbelief.* The father of the demon-possessed boy is not a man with a perfected faith — he is a man with effort. *A just man falleth seven times, and riseth up again* (Mishlei/Proverbs 24:16). **Q14 NT-Lord flag** queued for S184.$n$,$n$Proverbs 24:16 — *a just man falleth seven times, and riseth up again.* A half believing man who cries for help is the just man mid fall, already rising.$n$),
(2522,'enoch','1-enoch',10,17,$n$And then shall all the righteous escape, And shall live till they beget thousands of children, And all the days of their youth and their old age Shall they complete in peace.$n$,'canon','isaiah',46,10,$n$thread:effort-over-accomplishment | All the righteous escape and live — the gathering completing; Enoch witnesses the end declared from the beginning$n$,$n$Isaiah 46:10 — *Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:* *And then shall all the righteous escape, And shall live till they beget thousands of children, And all the days of their youth and their old age Shall they complete in peace.* (1 Enoch 10:17) The end was named before the road began, and it is a good end: *My counsel shall stand*. The righteous in Enoch finish their days in peace, and Isaiah says the one who declared *the end from the beginning* has already settled it. The gathering is not in doubt, so the man who falls and rises is walking toward it.$n$,229,$n$All the righteous escape and live — the gathering completing; Enoch witnesses the end declared from the beginning$n$,$n$Isaiah 46:10 — *saying, My counsel shall stand, and I will do all my pleasure.* His counsel stands, so the end he declared, the gathering home, will come, and the one who rises is on that road.$n$),
(5179,'canon','mark',9,24,$n$And straightway the father of the child cried out, and said with tears, Lord, I believe; help you my unbelief.$n$,'canon','isaiah',41,10,$n$thread:effort-over-accomplishment | *Fear thou not; for I am with thee* (Yeshayahu/Isaiah 41:10).$n$,$n$Isaiah 41:10 — *Fear thou not; for I am with thee: be not dismayed; for I am thy Elohim (God): I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.* *And straightway the father of the child cried out, and said with tears, Lord, I believe; help you my unbelief.* (Mark 9:24) The father has no steady faith to offer, only a cry. The answer was written long before: *I will help thee*, from the one who is *thy Elohim (God)*. The man who stumbles is not told to be clean first. He is told not to fear, because he will be held up.$n$,229,$n$*Fear thou not; for I am with thee* (Yeshayahu/Isaiah 41:10).$n$,$n$Isaiah 41:10 — *I will strengthen thee; yea, I will help thee; yea, I will uphold thee.* The help does not wait on a clean record, because the one who speaks promises to strengthen and uphold.$n$),
(5202,'canon','mark',10,21,$n$Then Yahusha (Jesus) beholding him loved him, and said unto him, One thing you lackest: go your way, sell whatsoever you have, and give to the poor, and you shall have treasure in heaven: and come, take up the cross, and follow me.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *One thing thou lackest.* The kingdom is entered not by counting accomplishment but by taking the next step in love. *A just man falleth seven times, and riseth up again* (Mishlei/Proverbs 24:16).$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *Then Yahusha (Jesus) beholding him loved him, and said unto him, One thing you lackest: go your way, sell whatsoever you have, and give to the poor, and you shall have treasure in heaven: and come, take up the cross, and follow me.* (Mark 10:21) Yahusha (Jesus) looked at the man and loved him, and then named one thing he lacked. What he asked was a step, not more accomplishment to count. The proverb says the just man *riseth up again*, so the road is the next step after coming short, taken in love.$n$,229,$n$*One thing thou lackest.* The kingdom is entered not by counting accomplishment but by taking the next step in love. *A just man falleth seven times, and riseth up again* (Mishlei/Proverbs 24:16).$n$,$n$Proverbs 24:16 — *falleth seven times, and riseth up again: but the wicked shall fall into mischief.* The next step after coming short is what the proverb counts, not a record of what was achieved.$n$),
(5228,'canon','mark',11,22,$n$And Yahusha (Jesus) answering says unto them, Have faith in Elohim (God).$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *Have faith in Elohim (God).* The mountain-removing word is not formula but trust-walking (Mishlei/Proverbs 24:16).$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *And Yahusha (Jesus) answering says unto them, Have faith in Elohim (God).* (Mark 11:22) *Have faith in Elohim (God)* is trust that keeps walking, not a formula. The just man's trust is that he gets up after a fall, seven times over, because he looks to the one who sets him on his feet. The wicked stop their ears and call the fall the end.$n$,229,$n$*Have faith in Elohim (God).* The mountain-removing word is not formula but trust-walking (Mishlei/Proverbs 24:16).$n$,$n$Proverbs 24:16 — *falleth seven times, and riseth up again.* Faith in Elohim (God) is what gets the just man up again after each fall.$n$),
(5229,'canon','mark',11,22,$n$And Yahusha (Jesus) answering says unto them, Have faith in Elohim (God).$n$,'canon','isaiah',41,10,$n$thread:effort-over-accomplishment | *Fear thou not; for I am with thee* (Yeshayahu/Isaiah 41:10).$n$,$n$Isaiah 41:10 — *Fear thou not; for I am with thee: be not dismayed; for I am thy Elohim (God): I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.* *And Yahusha (Jesus) answering says unto them, Have faith in Elohim (God).* (Mark 11:22) To have faith in Elohim (God) is to hear him say *Fear thou not; for I am with thee*. The faith rests on what he says he will do, not on a clean record. The man held up is a man who has stumbled, and the hand holding him is *the right hand of my righteousness*, not his own.$n$,229,$n$*Fear thou not; for I am with thee* (Yeshayahu/Isaiah 41:10).$n$,$n$Isaiah 41:10 — *I will uphold thee with the right hand of my righteousness.* Faith rests on his hand holding the stumbling man up, not on the man's own righteousness.$n$),
(5258,'canon','mark',12,41,$n$And Yahusha (Jesus) sat over against the treasury, and beheld how the people cast money into the treasury: and many that were rich cast in much.$n$,'canon','1-samuel',16,7,$n$thread:effort-over-accomplishment | *Man looketh on the outward appearance, but Yahuah (the LORD) looketh on the heart* (1 Sh'mu'el/Samuel 16:7).$n$,$n$1 Samuel 16:7 — *But Yahuah (LORD) said unto Samuel, Look not on his countenance, or on the height of his stature; because I have refused him: for Yahuah (LORD) seeth not as man seeth; for man looketh on the outward appearance, but Yahuah (LORD) looketh on the heart.* *And Yahusha (Jesus) sat over against the treasury, and beheld how the people cast money into the treasury: and many that were rich cast in much.* (Mark 12:41) Yahusha (Jesus) sits and watches the money go in, and *many that were rich* put in much. Samuel is told the same measure long before: man looks at the outside, but Yahuah (LORD) looks at the heart. The heart behind the offering is weighed, not the size of the pile.$n$,229,$n$*Man looketh on the outward appearance, but Yahuah (the LORD) looketh on the heart* (1 Sh'mu'el/Samuel 16:7).$n$,$n$1 Samuel 16:7 — *man looketh on the outward appearance, but Yahuah (LORD) looketh on the heart.* He weighs the heart behind the gift, so a large pile proves nothing and a small one can be the more.$n$),
(5257,'canon','mark',12,41,$n$And Yahusha (Jesus) sat over against the treasury, and beheld how the people cast money into the treasury: and many that were rich cast in much.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *The widow's two mites and the rich-man's much give the same Elohim (God) the more and the less by the same standard.* The widow's effort is what is *more*.$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *And Yahusha (Jesus) sat over against the treasury, and beheld how the people cast money into the treasury: and many that were rich cast in much.* (Mark 12:41) The rich *cast in much* and it counts for little. The proverb sets the measure at the rising, not at the pile. A man who falls seven times and gets up has given more of himself than a full hand of coin that never touched the heart.$n$,229,$n$*The widow's two mites and the rich-man's much give the same Elohim (God) the more and the less by the same standard.* The widow's effort is what is *more*.$n$,$n$Proverbs 24:16 — *a just man falleth seven times, and riseth up again.* The measure is the getting up after falling, not the size of what was given or gained.$n$),
(5332,'canon','mark',14,66,$n$And as Peter was beneath in the palace, there comes one of the maids of the high priest:$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *Peter's threefold denial — the failure that does not annul the calling.* Effort over accomplishment — the falling-and-rising-again of Mishlei (Proverbs) 24:16.$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *And as Peter was beneath in the palace, there comes one of the maids of the high priest:* (Mark 14:66) Peter is down in the palace and a maid of the high priest is coming for him. He is about to fall, and badly. The proverb says the just man falls and *riseth up again*, so the failure does not cancel the calling. What counts is whether he gets up.$n$,229,$n$*Peter's threefold denial — the failure that does not annul the calling.* Effort over accomplishment — the falling-and-rising-again of Mishlei (Proverbs) 24:16.$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again.* Peter's coming fall is the kind the just man rises from, so it does not annul his calling.$n$),
(5333,'canon','mark',14,66,$n$And as Peter was beneath in the palace, there comes one of the maids of the high priest:$n$,'canon','john',21,15,$n$thread:effort-over-accomplishment | *The same Peter the King names Cephas at the start is the same Peter the King restores at John 21* (Yochanan/John 21:15-19).$n$,$n$John 21:15 — *So when they had dined, Yahusha (Jesus) saith to Simon Peter, Simon, son of Jonah, lovest thou me more than these? He saith unto him, Yea, Adonai (Lord); thou knowest that I love thee. He saith unto him, Feed my lambs.* *And as Peter was beneath in the palace, there comes one of the maids of the high priest:* (Mark 14:66) Peter denied him down in the high priest's palace, and here Yahusha (Jesus) asks him *lovest thou me more than these*. He is not thrown out. He is given lambs to feed. The man who fell is the man sent to work.$n$,229,$n$*The same Peter the King names Cephas at the start is the same Peter the King restores at John 21* (Yochanan/John 21:15-19).$n$,$n$John 21:15 — *Simon, son of Jonah, lovest thou me more than these?* The fallen man is asked about love and handed lambs, which is the rising after the fall.$n$),
(5368,'canon','mark',16,7,$n$But go your way, tell his disciples and Peter that he goes before you into Galilee: there shall you see him, as he said unto you.$n$,'canon','proverbs',24,16,$n$thread:effort-over-accomplishment | *Tell his disciples and Peter that he goeth before you into Galilee.* The angel's specific naming of Peter — the falling disciple singled out for the restoration message. *A just man falleth seven times, and riseth up again* (Mishlei/Proverbs 24:16).$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* *But go your way, tell his disciples and Peter that he goes before you into Galilee: there shall you see him, as he said unto you.* (Mark 16:7) The word is sent to *his disciples and Peter*, and Peter is named out loud. The one who fell is singled out to hear that Yahusha (Jesus) is going ahead and will be seen. That is the proverb at work: the just man falls and *riseth up again*.$n$,229,$n$*Tell his disciples and Peter that he goeth before you into Galilee.* The angel's specific naming of Peter — the falling disciple singled out for the restoration message. *A just man falleth seven times, and riseth up again* (Mishlei/Proverbs 24:16).$n$,$n$Proverbs 24:16 — *For a just man falleth seven times, and riseth up again.* Naming Peter in the message sends the restoring word to the one who fell, so he can rise.$n$),
(5369,'canon','mark',16,7,$n$But go your way, tell his disciples and Peter that he goes before you into Galilee: there shall you see him, as he said unto you.$n$,'canon','john',21,15,$n$thread:effort-over-accomplishment | The resurrection word sent to the denying apostle by name (Yochanan/John 21:15-19).$n$,$n$John 21:15 — *So when they had dined, Yahusha (Jesus) saith to Simon Peter, Simon, son of Jonah, lovest thou me more than these? He saith unto him, Yea, Adonai (Lord); thou knowest that I love thee. He saith unto him, Feed my lambs.* *But go your way, tell his disciples and Peter that he goes before you into Galilee: there shall you see him, as he said unto you.* (Mark 16:7) Peter was named in the word the women carried, and when Yahusha (Jesus) meets him he asks only *lovest thou me*. Then comes *Feed my lambs*. The man who denied him is sent back to work, not struck off the list.$n$,229,$n$The resurrection word sent to the denying apostle by name (Yochanan/John 21:15-19).$n$,$n$John 21:15 — *thou knowest that I love thee. He saith unto him, Feed my lambs.* The denier is answered with a commission, so the word sent to Peter by name is kept.$n$),
(5374,'canon','mark',16,14,$n$Afterward he appeared unto the eleven as they sat at meat, and upbraided them with their unbelief and hardness of heart, because they believed not them which had seen him after he was risen.$n$,'canon','john',21,15,$n$thread:effort-over-accomplishment | *The King upbraiding the eleven for their unbelief.* The rebuke and the commission together, one motion of the same patient Father — the same Peter restored at Yochanan (John) 21.$n$,$n$John 21:15 — *So when they had dined, Yahusha (Jesus) saith to Simon Peter, Simon, son of Jonah, lovest thou me more than these? He saith unto him, Yea, Adonai (Lord); thou knowest that I love thee. He saith unto him, Feed my lambs.* *Afterward he appeared unto the eleven as they sat at meat, and upbraided them with their unbelief and hardness of heart, because they believed not them which had seen him after he was risen.* (Mark 16:14) He upbraided the eleven for *unbelief and hardness of heart*, and the next thing he does is give work. At the table with Peter he asks *lovest thou me* and answers with the call to feed. Rebuke and commission come together from the same Yahusha (Jesus).$n$,229,$n$*The King upbraiding the eleven for their unbelief.* The rebuke and the commission together, one motion of the same patient Father — the same Peter restored at Yochanan (John) 21.$n$,$n$John 21:15 — *So when they had dined, Yahusha (Jesus) saith to Simon Peter.* The scolded disciples are the ones he still feeds and sends, so the rebuke and the commission are one motion.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (229, 'effort-over-accomplishment', $n$Effort over accomplishment — the same God says both$n$, $n$Effort over accomplishment — the just man falls seven times and rises, and the one who gives the new heart says both halves (Proverbs 24; Ezekiel 36; Ephesians 2; Isaiah 46)$n$, $n$The Reformation reader has been shaped to believe two thoughts cannot stand in the same paragraph. The same God who said *not for your righteousness do I do this, but for my own name's sake* — also said *depart from me, ye that work iniquity, I never knew you.* The same God who said *for by grace are ye saved through faith* — also said *whosoever hath sinned against me, him will I blot out of my book.* The same God who said *I will give you a new heart* — also said *ye shall loathe yourselves in your own sight for your iniquities.*

The Reformation kept the *for my name's sake* half and put a period where there should have been a colon. The rabbinic system kept the *depart from me* half and built a flesh-righteousness gospel. The framework holds both halves because scripture holds both halves. The place where they hold together is the phrase that names the diagnostic: **effort over accomplishment.**

*"For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief."* (Proverbs 24:16)

The just is not the man who never fell. The wicked is not the man who failed to accomplish. What separates them is not the verdict — *none worthy* has already fallen on every flesh — but the heart's response. The just rises. The wicked *stops his ears* (Proverbs 28:9; Zechariah 7:11-12; Acts 7:57). Open ears and a returning heart, even after seven falls, is the sign of life; stopped ears, even after a hundred sermons, is the sign of death.

The new heart's signature response to grace is not the boast. It is the hanging head — *ye shall loathe yourselves in your own sight for your iniquities* (Ezekiel 36:31; 20:43; Job 42:5-6; Isaiah 6:5; Daniel 9:5). The Reformation gospel produces a head that holds itself up because it is *saved.* The rabbinic gospel produces a head that holds itself up because it is *righteous.* The framework's new heart produces a head that goes lower the more it sees His mercy.

*"Remember the former things of old: for I am El, and there is none else; I am Elohim (God), and there is none like me, Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure."* (Isaiah 46:9-10)

The whole architecture is sealed by the end the Father declared from the beginning. The end is the gathering — the twelve tribes home, the new heart given, the kingdom of priests, the Way restored. Every system that denies the gathering denies the end; every system that denies the end calls Him a liar; to call Him a liar is to reject the mercy that hangs on His name. The architecture stands or falls as one piece.

Companion threads: `grace-from-names-sake` carries the name's-sake-mercy pillar; `new-heart` carries the Torah-internalized pillar; `post-harvest-sifting` carries the wheat-sifting pillar; `grace-and-the-opportunity-that-can-be-lost` carries the standing-can-be-forfeit warning at the Matt 6 anchor. This thread anchors the architecture at the Proverbs 24:16 hinge and adds the stopped-ears discriminator, the hanging-heads sign, and the end-declared seal.$n$, $n$It ain't new. The one who says *I do not this for your sakes* is the same one who says *depart from me, ye that work iniquity*, and the one who promises a new heart is the same one who says that heart will loathe itself for what it did. Both are in the same book, often in the same chapter, and they were never two voices. Proverbs puts the whole of it in one line:

*For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.* (Proverbs 24:16)

The just man is not the man who never fell. Nobody is that man:

*For there is not a just man upon earth, that doeth good, and sinneth not.* (Ecclesiastes 7:20)

*If they sin against thee, (for there is no man that sinneth not,) and thou be angry with them, and deliver them to the enemy, so that they carry them away captives unto the land of the enemy, far or near;* (1 Kings 8:46)

*For all have sinned, and come short of the glory of Elohim (God);* (Romans 3:23)

So the line between the just and the wicked is not drawn at the fall. It is drawn at what the man does after it. The just rises. The wicked stops his ears:

*He that turneth away his ear from hearing the law, even his prayer shall be abomination.* (Proverbs 28:9)

*But they refused to hearken, and pulled away the shoulder, and stopped their ears, that they should not hear.* (Zechariah 7:11)

Hear what is done for the house, and for whose sake:

*Therefore say unto the house of Yashar'el (Israel), Thus saith Adonai Yahuah (the Lord GOD); I do not this for your sakes, O house of Yashar'el (Israel), but for mine holy name’s sake, which ye have profaned among the heathen, whither ye went.* (Ezekiel 36:22)

*A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.* (Ezekiel 36:26)

*And I will put my spirit within you, and cause you to walk in my statutes, and ye shall keep my judgments, and do them.* (Ezekiel 36:27)

And read what the new heart does first, in the very same chapter:

*Then shall ye remember your own evil ways, and your doings that were not good, and shall lothe yourselves in your own sight for your iniquities and for your abominations.* (Ezekiel 36:31)

That is the sign of the new heart: not a head held high because it is saved, and not a head held high because it is righteous, but a head that goes lower the more mercy it sees. Job, Isaiah and Daniel all have it:

*I have heard of thee by the hearing of the ear: but now mine eye seeth thee.* (Job 42:5)

*Wherefore I abhor myself, and repent in dust and ashes.* (Job 42:6)

*Then said I, Woe is me! for I am undone; because I am a man of unclean lips, and I dwell in the midst of a people of unclean lips: for mine eyes have seen the King, Yahuah Tseva'ot (LORD of hosts).* (Isaiah 6:5)

*We have sinned, and have committed iniquity, and have done wickedly, and have rebelled, even by departing from thy precepts and from thy judgments:* (Daniel 9:5)

The one who gives the heart for his own name's sake is the one who also says a name can be blotted out, and that a righteous man who turns away is not carried by what he did before:

*And Yahuah (LORD) said unto Moses, Whosoever hath sinned against me, him will I blot out of my book.* (Exodus 32:33)

*But when the righteous turneth away from his righteousness, and committeth iniquity, and doeth according to all the abominations that the wicked man doeth, shall he live? All his righteousness that he hath done shall not be mentioned: in his trespass that he hath trespassed, and in his sin that he hath sinned, in them shall he die.* (Ezekiel 18:24)

*And then will I profess unto them, I never knew you: depart from me, ye that work iniquity.* (Matthew 7:23)

*He that overcometh, the same shall be clothed in white raiment; and I will not blot out his name out of the book of life, but I will confess his name before my Father, and before his angels.* (Revelation 3:5)

Paul holds both halves in three verses, and the pulpit usually stops reading after the second:

*For by grace are ye saved through faith; and that not of yourselves: it is the gift of Elohim (God):* (Ephesians 2:8)

*Not of works, lest any man should boast.* (Ephesians 2:9)

*For we are his workmanship, created in HaMashiach Yahusha (Christ Jesus) unto good works, which Elohim (God) hath before ordained that we should walk in them.* (Ephesians 2:10)

The gift is for his name's sake, and the walk is the works he ordained. The one who keeps the first half and drops the second has put a period where there was a colon. The one who keeps the second half and drops the first builds a righteousness of the flesh and holds his head up for it. Scripture holds both, because it is one voice. Yahusha (Jesus) sets the measure for a brother at seven times in a day, the proverb's own number:

*And if he trespass against thee seven times in a day, and seven times in a day turn again to thee, saying, I repent; thou shalt forgive him.* (Luke 17:4)

And the whole of it is sealed by the end he declared before any of it began:

*Remember the former things of old: for I am Elohim (God), and there is none else; I am Elohim (God), and there is none like me,* (Isaiah 46:9)

*Declaring the end from the beginning, and from ancient times the things that are not yet done, saying, My counsel shall stand, and I will do all my pleasure:* (Isaiah 46:10)

The end is the gathering: the twelve tribes home, the new heart given, the statutes walked in. The man who falls and rises is on that road. The man who stops his ears has left it, whatever he accomplished. Effort over accomplishment is not a loophole. It is the shape of the whole book.$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 229 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 229 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (effort-over-accomplishment) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — effort-over-accomplishment done.'
